result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/dupfind.py", "content": "#!/usr/bin/env python3
"""dupfind.py - find groups of duplicate files in a directory tree.

Strategy: group files by size (cheap), then sha256-hash only same-size
candidates, streaming in 64KB chunks. Report duplicate groups sorted by
wasted bytes descending.
"""

from __future__ import annotations

import argparse
import hashlib
import os
import sys
from collections import defaultdict
from pathlib import Path

CHUNK_SIZE = 64 * 1024


def iter_files(root: Path):
    """Yield all regular files under root (skips symlinks)."""
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort()
        for name in sorted(filenames):
            p = Path(dirpath) / name
            if p.is_symlink():
                continue
            try:
                if p.is_file():
                    yield p
            except OSError:
                continue


def hash_file(path: Path) -> str:
    """Stream sha256 of path's contents."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while chunk := f.read(CHUNK_SIZE):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root: Path) -> list[list[Path]]:
    """Return list of duplicate groups (each with >= 2 paths), sorted lexically within group."""
    by_size = defaultdict(list)
    for p in iter_files(root):
        try:
            by_size[p.stat().st_size].append(p)
        except OSError:
            continue

    by_hash = defaultdict(list)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue
        for p in paths:
            try:
                by_hash[hash_file(p)].append(p)
            except OSError:
                continue

    groups = [sorted(g) for g in by_hash.values() if len(g) >= 2]
    return groups


def wasted_bytes(group: list[Path]) -> int:
    """Bytes wasted = size * (copies - 1). All files in a group share the same size."""
    size = group[0].stat().st_size
    return size * (len(group) - 1)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Find duplicate files by content.")
    parser.add_argument("root", type=Path, help="directory to scan")
    parser.add_argument(
        "--delete-keep-first",
        action="store_true",
        help="delete all but the first (lexically sorted) path in each group",
    )
    args = parser.parse_args(argv)

    if not args.root.is_dir():
        print(f"error: {args.root} is not a directory", file=sys.stderr)
        return 2

    groups = find_duplicates(args.root)
    groups.sort(key=wasted_bytes, reverse=True)

    total_wasted = 0
    for group in groups:
        w = wasted_bytes(group)
        total_wasted += w
        print(f"group ({w} bytes wasted):")
        for p in group:
            print(f"  {p}")

    print(f"total wasted bytes: {total_wasted}")

    if args.delete_keep_first:
        removed = 0
        freed = 0
        for group in groups:
            for p in group[1:]:
                try:
                    freed += p.stat().st_size
                    p.unlink()
                    removed += 1
                except OSError as e:
                    print(f"warning: could not remove {p}: {e}", file=sys.stderr)
        print(f"deleted {removed} file(s), freed {freed} byte(s)")

    return 0


if __name__ == "__main__":
    sys.exit(main())
